async function legacyHash(n){let h=2166136261;const feed=s=>{for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}};const ns=all(n);feed('[');for(let i=0;i<ns.length;i++){const x=ns[i],v={id:x.id,name:x.name,type:x.type};for(const k of ['x','y','width','height','visible','fills','strokes','layoutMode','itemSpacing','paddingTop','paddingBottom','reactions'])if(k in x)v[k]=x[k];if(x.type==='TEXT')v.text=x.characters;if(i)feed(',');feed(JSON.stringify(v));if(i%500===0){figma.ui.postMessage({status:'核对交互区 '+n.id+' · '+i+' / '+ns.length});await new Promise(r=>setTimeout(r,0));}}feed(']');return {hash:(h>>>0).toString(16),count:ns.length};}
async function resumeAudit(){await init();const frames=await Promise.all(RECOVERY.frames.map(id=>figma.getNodeByIdAsync(id))),after=snapshotFrames(frames);const ids=Object.keys(RECOVERY.before);const deleted=ids.filter(id=>!after[id]);const removedTextIds=RECOVERY.removed.map(n=>n.id);const preservedTextChanges=ids.filter(id=>after[id]&&RECOVERY.before[id].type==='TEXT'&&after[id].text!==RECOVERY.before[id].text);const reactionChanges=ids.filter(id=>after[id]&&JSON.stringify(after[id].reactions)!==JSON.stringify(RECOVERY.before[id].reactions));const removedNotRequested=deleted.filter(id=>!removedTextIds.includes(id)&&RECOVERY.before[id].name!=='Space');const branchHashes={};for(const id of ['1:43252','1:43254'])branchHashes[id]=await legacyHash(await figma.getNodeByIdAsync(id));const overflows=[],nonGray=[];for(const r of frames.filter(n=>n.visible)){const body=r.findOne(n=>n.name==='Content'),vp=body?.parent;if(body&&vp&&body.height>vp.height+.5)overflows.push({id:r.id,content:body.height,viewport:vp.height});for(const n of all(r))if('fills'in n&&Array.isArray(n.fills))for(const f of n.fills)if(f.type==='SOLID'&&(Math.abs(f.color.r-f.color.g)>.001||Math.abs(f.color.g-f.color.b)>.001))nonGray.push(n.id);}
return{status:'浅深指定文字与范围复核完成',applied:true,removedTextCount:removedTextIds.filter(id=>!after[id]).length,removedTexts:RECOVERY.removed,remainingSpecifiedTexts:matches().map(n=>({id:n.id,text:n.characters})),preservedTextChanges,reactionChanges,removedNotRequested,branchHashes,branchesUnchanged:branchHashes['1:43252'].hash==='c9acba72'&&branchHashes['1:43254'].hash==='d7d84039',visibleContentOverflows:overflows,nonGrayLayerIds:[...new Set(nonGray)],sections:sections.map(s=>({id:s.id,name:s.name,visibleFrames:s.children.filter(n=>n.visible&&n.type==='FRAME').length})),frames:frames.map(r=>({id:r.id,name:r.name,visible:r.visible,width:r.width,height:r.height})),comparisonCoverage:'Persisted pre-edit target-parent subtrees, both entire interaction sections using R3 baseline algorithm; all visible review screenshots additionally compared locally.',afterNodes:after};}

async function tighten(){await init();if(matches().length)throw Error('Expected copy cleanup completed');const beforeRx=rx(),mutatedNodeIds=[],changes=[];for(const id of RECOVERY.frames){const r=await figma.getNodeByIdAsync(id);if(!within(r))throw Error('Out of scope');const sh=r.children.find(n=>n.name==='Sheet');if(!sh)continue;const vp=sh.children.find(n=>n.name==='Sheet viewport'),body=vp.children.find(n=>n.name==='Content'),home=sh.children.find(n=>n.name==='Home indicator');const height=vp.y+body.height+32;if(height>sh.height+.1)throw Error('Unexpected expansion');const before={sheet:info(sh),viewport:info(vp),home:info(home)};sh.resize(sh.width,height);sh.y=r.height-height;vp.resize(vp.width,height-vp.y-12);home.y=height-14;mutatedNodeIds.push(sh.id,vp.id,home.id);changes.push({frameId:r.id,before,after:{sheet:info(sh),viewport:info(vp),home:info(home)},contentHeight:body.height});}await new Promise(r=>setTimeout(r,0));const afterRx=rx();return{status:'弹层相邻留白已收紧',applied:true,mutatedNodeIds,createdNodeIds:[],removedNodeIds:[],changes,reactionsUnchanged:JSON.stringify(beforeRx)===JSON.stringify(afterRx),remainingSpecifiedTextCount:matches().length,allowedSectionIds:SCOPE};}
